# -*- coding: utf-8 -*-
"""Lecture 42 vignette pool C -- Pulmonary Vascular Disorders: pulmonary embolism risk factors and presentation,
diagnosis (Wells score, PERC (Pulmonary Embolism Rule-out Criteria), D-dimer, imaging choice) and risk
stratification and treatment (slides 48-62).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Score items (s53 Wells, s54 PERC): every element is stated in the stem, including whether pulmonary embolism is
judged more likely than any alternative; the key's explanation shows the sum item by item; numeric options are
ascending and marked ordered. Boundary values are avoided (no heart rate of exactly 100, no saturation of 94-95%,
no immobilization of exactly 3 days, no surgery exactly 4 weeks ago, no cancer treated exactly 6 months ago, no
skin cancer). Risk stratification (s58) uses the slide's three groups only (no intermediate-high / -low split).
No anticoagulant or thrombolytic drug is named. Echocardiography is never called diagnostic for embolism (s56).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l42_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


